 d={'schema':'opentallas.fe_consumer_reset_ack_source.v1','status':'Source-candidate ACK ABI; default-off; physical successor views and actual production drivers OPEN','macro':'OT_SPVM_RESET_ACK','production_parameters':{'VMFE_R':R,'VMFE_XRT':1,'VMFE_CCA':1},'guarded_parent_ports':{'rst_ack':f'output wire [{40+24*R}:0]','rst_ack_s':'output wire [3:0]'},'guarded_leaf_ports':{'dsfd_vm_clt / dsfd_vm_fsr / dsfd_vm_fxs / dsfd_vm_flt / dsfd_vm_fld / dsfd_vm_fxr / dsfd_vm_fxa / dsfd_vm_fxb':'input wire reset_epoch_n; output wire rst_ack','dsfd_vm_fcw':'output wire [1:0] rst_ack','dsfd_vm_fcn / dsfd_vm_fcc':'output wire [1:0] rst_ack; output wire [1:0] rst_ack_s','dsfd_vm_wfc_ep':'output wire rst_ack','ot_s81_engine_adapter':'output wire rst_ack_c, rst_ack_e','ot_s81_pulse_cdc':'output wire reset_live_s, reset_live_d','ot_async_fifo':'output wire wr_reset_live, rd_reset_live'},'helper_contract':{'module':'dsfd_vm_reset_ack','parameters':{'N':1},'ports':['clk','request_n','local_release[N-1:0]','consumer_live','ack'],'request_n':'External per-domain epoch reset upstream of local conditioners/forwarding. Never substitute final local rn for request.','witness':'Async clears on request assertion even if clock stops. After request release, must sample all supplied actual local states LOW at a consumer edge. Missed reset remains unacknowledged until a valid epoch reset.','release':'ACK requires witness, all final local states HIGH, and actual local online/rendezvous. ack_q rises at a later consumer edge; output also gates by actual local release/live so a real local reset/online loss drops it.','initialization_edge':'At a witnessed LOW edge, existing consumers execute their real reset initialization. Registering rn_r/rn_q HIGH and sampling their old LOW initializes consumer state that edge; ACK rises on a later edge. No ACK state gates datapath.'},'ack_nodes':nodes,'counts':{'serial_ack':41+24*R,'stream_ack':4,'ack_helpers':len(nodes),'new_ack_only_ff':2*len(nodes),'default_undefined_new_state':0,'price_scope':'Nominal source-instance price; retain full234FF atR3. Verilator coalesces equivalent state under ideal common ck; no physical savings or reprice inferred.'},'additional_raw_epoch_reset_leaf_pins':35+24*R,'cdc_evidence':{'async_fifo_wr_live':'wr_domain_rst_n && wr_online && rd_online_w2','async_fifo_rd_live':'rd_domain_rst_n && rd_online && wr_online_r2','ratio_fifo_alternative':'CCA0 cross ACKs include actual w_live/r_live derived from S_RUN and sampled peer state; exported ports retained, distinct source graph required if this configuration is selected','adapter':'Both command and done FIFO actual local rendezvous states included independently in each adapter domain; online alone is insufficient'},'reset_free_consumers':[f'g_ll[{i}]/u_m' for i in range(10)]+['g_kr/u_kl','g_kr/u_kr'],'parent_hookup_requirement':'Synchronize each genuine ACK into controller domain before reduction. Do not reduce raw multi-domain ACK vectors combinationally. Actual controller/delivery/source netlist binding owned by parent, not assigned here.','history':'Existing CLOSED default leaves remain historical. ACK ports/state require successor source-bound pin views and SS/FF closure; no replacement eligibility inferred.','source_sha256':{p:sha(ROOT/p) for p in files},'minimum_proof':{'path':str((OUT/'proof.json').relative_to(ROOT)),'sha256':sha(OUT/'proof.json')},'full_fe_source_elaboration':{'path':str((OUT/'elaboration_receipt.json').relative_to(ROOT)),'sha256':sha(OUT/'elaboration_receipt.json')},'ideal_clock_optimizer_census':{'path':str((OUT/'ideal_clock_elaboration_variables.json').relative_to(ROOT)),'sha256':sha(OUT/'ideal_clock_elaboration_variables.json')},'numerical_behavior':'No existing numerical/valid/reset stage or clock modified. Minimum default-vs-ACK numerical trace parity PASS; full production parent/model proof owned by parent.'}
